-- PolarDB-X: the two DISTINCT-add pairs of the second campaign (seeds 3 and 7 of
-- bridge/gen_mysql_db.py), on their databases, with variants.
-- expected: each query with DISTINCT * returns the rows of the query just before it.
DROP DATABASE IF EXISTS vs_dd3; CREATE DATABASE vs_dd3; USE vs_dd3;
CREATE TABLE t1 (c1 VARCHAR(20) COLLATE utf8mb4_bin, c4 DECIMAL(10,2)) ENGINE=InnoDB;
INSERT INTO t1 VALUES ('-3', 7.5), ('-3', 5.75), ('3', NULL), (NULL, 1.5), (NULL, 10), ('5', NULL);
CREATE TABLE t2 (c1 DECIMAL(10,2), c2 INT, c3 INT, c14 INT, c15 DECIMAL(10,2), rid INT PRIMARY KEY) ENGINE=InnoDB;
INSERT INTO t2 VALUES (5.25, NULL, NULL, 2, NULL, 0), (3, NULL, -1, 1, 7.25, 1), (2, 2, 10, 2, 3, 2), (2.5, NULL, 5, 3, 10.75, 3), (-2.25, 2, 0, 3, 4, 4), (-1, 0, -1, NULL, 1.5, 5), (NULL, NULL, 3, 10, 0, 6), (2, NULL, 1, 3, 3, 7), (5.25, 0, NULL, NULL, 10.25, 8), (1, 2, 1, 1, -0.25, 9), (5, 1, 4, 4, NULL, 10), (4, -1, 10, NULL, 1.25, 11);
CREATE TABLE t3 (c1 INT, c2 VARCHAR(20) COLLATE utf8mb4_bin, c3 DATE, c6 DECIMAL(10,2), c7 INT, c8 INT, c9 INT) ENGINE=InnoDB;
INSERT INTO t3 VALUES (-1, '10', NULL, 2.25, 4, 5, -3), (0, '', '2024-01-28', 0, 0, 5, 2), (1, '1', NULL, 1.75, NULL, 0, 4), (1, '10', '2024-02-01', NULL, 10, 1, 7), (5, 'b', '2024-12-28', 3, NULL, NULL, 7), (-1, 'a', '2024-02-28', 4, 7, -3, 3), (NULL, ' 1', '2024-12-01', NULL, 1, 2, 3), (NULL, NULL, '2024-01-28', 2, 5, 4, 0), (7, 'x', '2024-01-01', NULL, 5, 2, 2), (3, '-1', '2024-01-01', NULL, NULL, 2, -1), (1, 'a', '2024-01-28', NULL, 4, 5, 3), (0, '0', '2024-01-28', 3, 3, 1, 3), (2, '1', '2024-02-01', 5.75, 0, 4, 2), (2, '01', '2024-12-01', -1, 1, 0, 7), (NULL, '-3', '2024-02-28', 1.5, -1, 1, 2), (3, 'b', '2024-01-28', 2, 5, 1, 0), (4, '2', '2024-02-01', 2, NULL, NULL, 2), (10, '10', '2024-01-15', NULL, 1, 2, -1), (1, 'x', '2024-01-01', 2.75, 4, NULL, NULL), (-1, '', '2024-01-28', -3, 0, 1, -1), (NULL, 'A', '2024-12-01', NULL, -1, NULL, 5), (4, 'x', '2024-01-28', 0.75, 7, NULL, NULL), (2, NULL, '2024-01-15', 7.75, 0, 10, 3), (2, 'b', '2024-12-15', -2.75, 2, -3, 2), (3, 'a ', NULL, 1.75, 1, 7, 0), (1, 'B', '2024-02-15', 4.25, 4, 2, NULL), (4, 'a ', '2024-02-15', NULL, NULL, 2, NULL), (-1, '7', '2024-01-01', NULL, -3, 2, 2);
CREATE INDEX i0 ON t3 (c6, c1);
CREATE INDEX i1 ON t1 (c4);
CREATE UNIQUE INDEX i2 ON t3 (c7);
CREATE INDEX i3 ON t2 (c3, c15, c1);
CREATE INDEX i4 ON t3 (c1, c6, c9);
CREATE INDEX i5 ON t1 (c1, c4);
ANALYZE TABLE t1;
ANALYZE TABLE t2;
ANALYZE TABLE t3;
SELECT 'seed 3 D1 reduced original' AS q;
SELECT t1a.c1 AS k1 FROM t1 AS t1a WHERE NOT (t1a.c1 IN (SELECT t1i5.c4 FROM t1 AS t1i5 WHERE t1a.c4 <= 10));
SELECT 'seed 3 D2 reduced mutant (DISTINCT * in the subquery)' AS q;
SELECT t1a.c1 AS k1 FROM t1 AS t1a WHERE NOT (t1a.c1 IN (SELECT t1i5.c4 FROM (SELECT DISTINCT * FROM t1 AS t1i5) AS t1i5 WHERE t1a.c4 <= 10));
SELECT 'seed 3 D3 NOT IN spelling' AS q;
SELECT t1a.c1 AS k1 FROM t1 AS t1a WHERE t1a.c1 NOT IN (SELECT t1i5.c4 FROM t1 AS t1i5 WHERE t1a.c4 <= 10);
SELECT 'seed 3 D4 the IN (not negated)' AS q;
SELECT t1a.c1 AS k1 FROM t1 AS t1a WHERE t1a.c1 IN (SELECT t1i5.c4 FROM t1 AS t1i5 WHERE t1a.c4 <= 10);
SELECT 'seed 3 D5 the IN with DISTINCT *' AS q;
SELECT t1a.c1 AS k1 FROM t1 AS t1a WHERE t1a.c1 IN (SELECT t1i5.c4 FROM (SELECT DISTINCT * FROM t1 AS t1i5) AS t1i5 WHERE t1a.c4 <= 10);
SELECT 'seed 3 D6 the predicate per row' AS q;
SELECT t1a.c1, t1a.c4, NOT (t1a.c1 IN (SELECT t1i5.c4 FROM t1 AS t1i5 WHERE t1a.c4 <= 10)) AS p FROM t1 AS t1a;
SELECT 'seed 3 D7 the predicate per row, DISTINCT *' AS q;
SELECT t1a.c1, t1a.c4, NOT (t1a.c1 IN (SELECT t1i5.c4 FROM (SELECT DISTINCT * FROM t1 AS t1i5) AS t1i5 WHERE t1a.c4 <= 10)) AS p FROM t1 AS t1a;
SELECT 'seed 3 D8 t1' AS q;
SELECT * FROM t1;
USE information_schema; DROP DATABASE vs_dd3;
DROP DATABASE IF EXISTS vs_dd7; CREATE DATABASE vs_dd7; USE vs_dd7;
CREATE TABLE t1 (c1 DECIMAL(10,2), c4 DECIMAL(10,2)) ENGINE=InnoDB;
