CREATE INDEX i0 ON t3 (c8, c9, c6);
CREATE INDEX i1 ON t1 (c1, c4);
CREATE UNIQUE INDEX i2 ON t2 (c1, c3, c15);
CREATE INDEX i3 ON t3 (c1, c3, c9);
CREATE INDEX i4 ON t3 (c8);
