CREATE INDEX i7 ON t3 (c8, c2, c6);
ANALYZE TABLE t1;
ANALYZE TABLE t2;
ANALYZE TABLE t3;
SELECT 'seed 7 D1 arm (reduced right side)' AS q;
SELECT t1a.c1 AS k0, t1b.c1 AS k1 FROM t1 AS t1a LEFT JOIN t1 AS t1b ON t1b.c1 < 1 WHERE (t1b.c1, t1b.c4) IN (SELECT t2i21.c3, t2i21.c15 FROM t2 AS t2i21 WHERE t2i21.c1 IS NULL);
SELECT 'seed 7 D2 arm, DISTINCT * on t1a' AS q;
SELECT t1a.c1 AS k0, t1b.c1 AS k1 FROM (SELECT DISTINCT * FROM t1 AS t1a) AS t1a LEFT JOIN t1 AS t1b ON t1b.c1 < 1 WHERE (t1b.c1, t1b.c4) IN (SELECT t2i21.c3, t2i21.c15 FROM t2 AS t2i21 WHERE t2i21.c1 IS NULL);
SELECT 'seed 7 D3 reduced arm, ON (0)' AS q;
SELECT t1a.c1 AS k0, t1b.c1 AS k1 FROM t1 AS t1a LEFT JOIN t1 AS t1b ON (0) WHERE (t1b.c1, t1b.c4) IN (SELECT t2i21.c3, t2i21.c15 FROM t2 AS t2i21);
SELECT 'seed 7 D4 reduced arm, ON (0), DISTINCT *' AS q;
SELECT t1a.c1 AS k0, t1b.c1 AS k1 FROM (SELECT DISTINCT * FROM t1 AS t1a) AS t1a LEFT JOIN t1 AS t1b ON (0) WHERE (t1b.c1, t1b.c4) IN (SELECT t2i21.c3, t2i21.c15 FROM t2 AS t2i21);
SELECT 'seed 7 D5 the subquery' AS q;
SELECT t2i21.c3, t2i21.c15, t2i21.c1 FROM t2 AS t2i21;
SELECT 'seed 7 D6 the join' AS q;
SELECT t1a.c1, t1b.c1, t1b.c4 FROM t1 AS t1a LEFT JOIN t1 AS t1b ON t1b.c1 < 1;
SELECT 'seed 7 D7 reduced original' AS q;
(SELECT t2a.c1 AS k0, t2a.c2 AS k1 FROM t2 AS t2a) EXCEPT (SELECT t1a.c1 AS k0, t1b.c1 AS k1 FROM t1 AS t1a LEFT JOIN t1 AS t1b ON (0) WHERE (t1b.c1, t1b.c4) IN (SELECT t2i21.c3, t2i21.c15 FROM t2 AS t2i21));
SELECT 'seed 7 D8 reduced mutant' AS q;
(SELECT t2a.c1 AS k0, t2a.c2 AS k1 FROM t2 AS t2a) EXCEPT (SELECT t1a.c1 AS k0, t1b.c1 AS k1 FROM (SELECT DISTINCT * FROM t1 AS t1a) AS t1a LEFT JOIN t1 AS t1b ON (0) WHERE (t1b.c1, t1b.c4) IN (SELECT t2i21.c3, t2i21.c15 FROM t2 AS t2i21));
USE information_schema; DROP DATABASE vs_dd7;
